(() => {
  const D=window.MORCHID_DATA;
  const app=document.getElementById('app');
  const STORAGE='morchid-progress-v3';
  const LEGACY_STORAGE='morchid-progress-v2';
  const readStorage=key=>{try{return localStorage.getItem(key)}catch(e){return null}};
  const writeStorage=(key,value)=>{try{localStorage.setItem(key,value)}catch(e){}};
  const state={
    theme:readStorage('morchid-theme')||'light',
    focus:false,
    qcmIndex:0,
    qcmAnswers:{},
    qcmHistory:{},
    qcmFilters:{domain:'all',difficulty:'all',status:'all',query:''},
    situationIndex:0,
    situationAnswers:{},
    flashIndex:0,
    flashFlipped:false,
    flashRatings:{},
    flashSchedule:{},
    inclusiveQuizIndex:0,
    inclusiveQuizScore:0,
    inclusiveQuizPicked:null,
    inclusivePillar:0,
    resourceSearch:'',
    resourceFilter:'all',
    termCategory:'all',
    examSetup:{count:25,minutes:60,domain:'all'},
    exam:null,
    readSchemes:[],
    readTerms:[],
    jury:[],
    activities:[],
    studyDays:[],
    readLessons:[],
    activeUnitId:null,
    activeUnitDate:''
  };
  let migratedLegacyProgress=false;
  try{
    const current=readStorage(STORAGE);
    const saved=JSON.parse(current??readStorage(LEGACY_STORAGE)??'{}');
    Object.assign(state,saved);
    state.qcmAnswers=saved.qcmAnswers||{};
    if(current===null&&saved.qcmAnswers){
      state.qcmAnswers=Object.fromEntries(Object.entries(saved.qcmAnswers).flatMap(([id,index])=>{const question=D.qcm.find(item=>item.id===id);if(!question)return [];const answerText=question.legacyOptions?.[index];const mapped=question.options.indexOf(answerText);return mapped<0?[]:[[id,mapped]]}));
      migratedLegacyProgress=true;
    }
    state.qcmHistory=saved.qcmHistory||{}; state.qcmFilters=saved.qcmFilters||state.qcmFilters;
    state.situationAnswers=saved.situationAnswers||{}; state.flashRatings=saved.flashRatings||{}; state.flashSchedule=saved.flashSchedule||{}; state.resourceSearch=saved.resourceSearch||''; state.resourceFilter=saved.resourceFilter||'all'; state.examSetup=saved.examSetup||state.examSetup;
    state.readSchemes=saved.readSchemes||[]; state.readTerms=saved.readTerms||[]; state.jury=saved.jury||[];
    state.activities=saved.activities||[]; state.studyDays=saved.studyDays||[]; state.readLessons=saved.readLessons||[]; state.activeUnitId=saved.activeUnitId||null; state.activeUnitDate=saved.activeUnitDate||'';
  }catch(e){}
  const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const save=()=>{writeStorage(STORAGE,JSON.stringify({...state,focus:false}))};
  if(migratedLegacyProgress)save();
  const rerenderSearch=input=>{const start=input.selectionStart,end=input.selectionEnd,id=input.id;render();const restored=document.getElementById(id);if(restored){restored.focus({preventScroll:true});if(typeof restored.setSelectionRange==='function')restored.setSelectionRange(start,end)}};
  const syncGlobalControls=()=>{const themeButton=document.getElementById('theme-toggle');const focusButton=document.getElementById('focus-toggle');if(themeButton){themeButton.setAttribute('aria-pressed',String(state.theme==='dark'));themeButton.setAttribute('aria-label',state.theme==='dark'?'تفعيل المظهر الفاتح':'تفعيل المظهر الداكن');themeButton.title=state.theme==='dark'?'تفعيل المظهر الفاتح':'تفعيل المظهر الداكن'}if(focusButton){focusButton.setAttribute('aria-pressed',String(state.focus));focusButton.setAttribute('aria-label',state.focus?'إيقاف وضع التركيز':'تفعيل وضع التركيز')}};
  const dayKey=()=>new Date().toISOString().slice(0,10);
  const recordActivity=(label,detail='')=>{
    const now=new Date(); const day=dayKey();
    if(!state.studyDays.includes(day))state.studyDays=[...state.studyDays.slice(-29),day];
    state.activities=[{label,detail,time:now.toLocaleTimeString('ar-MA',{hour:'2-digit',minute:'2-digit'}),day},...state.activities.filter(x=>x.label!==label).slice(0,4)]; save();
  };
  const percent=(a,b)=>b?Math.round(a/b*100):0;
  const domainName=id=>D.domainNames[id]||id;
  const route=()=>{if(location.hash)return location.hash.slice(1)||'home';const p=location.pathname.replace(/^\/+|\/+$/g,'');return p||'home'};
  const navKey=h=>h.startsWith('s-')?'schemes':h.startsWith('t-')?'glossary':h.startsWith('p-')?'plans':({schemes:'qcm',glossary:'flashcards',plans:'flashcards',path:'practice',practice:'qcm',quiz:'qcm',oral:'situations',jury:'progress',settings:'progress'}[h]||h);
  const toast=msg=>{const el=document.createElement('div');el.className='toast';el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),2400)};
  const pageHead=(eyebrow,title,sub='',action='')=>`<div class="page-head"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${action}</div>`;
  const backHead=(title,sub='')=>`<div class="detail-head"><a class="back-link" href="#home">‹ الرئيسية</a><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`;
  const tri=labels=>`<div class="triangle-css" role="img" aria-label="مثلث بيداغوجي يربط المعرفة والمدرس والمتعلم"><span class="tri-edge tri-left"></span><span class="tri-edge tri-right"></span><span class="tri-edge tri-base"></span><span class="tri-node tri-knowledge">${esc(labels[0])}</span><span class="tri-node tri-teacher">${esc(labels[1])}</span><span class="tri-node tri-learner">${esc(labels[2])}</span><span class="tri-relation tri-teach">التعليم</span><span class="tri-relation tri-learn">التعلم</span><span class="tri-relation tri-train">التكوين</span></div>`;
  const qcmStatus=q=>{const a=state.qcmAnswers[q.id];return a===undefined?'unanswered':a===q.answer?'correct':'wrong'};
  const qcmPool=()=>D.qcm.filter(q=>{
    const f=state.qcmFilters; const matchDomain=f.domain==='all'||q.domain===f.domain; const matchLevel=f.difficulty==='all'||q.difficulty===f.difficulty; const matchStatus=f.status==='all'||qcmStatus(q)===f.status; const text=`${q.question} ${q.concept} ${domainName(q.domain)}`.toLowerCase(); const matchQuery=!f.query||text.includes(f.query.toLowerCase()); return matchDomain&&matchLevel&&matchStatus&&matchQuery;
  });
  const qcmStats=()=>{const answered=Object.keys(state.qcmAnswers);const correct=answered.filter(id=>{const q=D.qcm.find(x=>x.id===id);return q&&state.qcmAnswers[id]===q.answer}).length;const masteryScore=D.qcm.reduce((sum,q)=>{const h=state.qcmHistory[q.id]||{correct:0,attempts:0};return sum+Math.min(100,Math.round((h.correct/Math.max(3,h.attempts))*100))},0);return {answered:answered.length,correct,accuracy:percent(correct,answered.length),mastery:percent(masteryScore,D.qcm.length*100)}};
  const recommendation=()=>{const stats=qcmStats(); if(!stats.answered)return {title:'ابدأ بسؤال واحد',text:'جلسة قصيرة الآن ستعطيك أول مؤشر على المجالات التي تحتاج تركيزًا.',href:'#qcm'}; const domains=Object.keys(D.domainNames).map(id=>{const qs=D.qcm.filter(q=>q.domain===id);const ans=qs.filter(q=>state.qcmAnswers[q.id]!==undefined);const ok=ans.filter(q=>state.qcmAnswers[q.id]===q.answer).length;return {id,total:qs.length,score:percent(ok,ans.length),answered:ans.length}}).filter(x=>x.answered).sort((a,b)=>a.score-b.score);const weak=domains[0];return weak?{title:`ركز على ${domainName(weak.id)}`,text:`دقتك الحالية في هذا المجال ${weak.score}%. أجب عن ثلاث بطاقات ثم راجع التفسير.`,href:'#qcm'}:{title:'حافظ على الإيقاع',text:'أكملت بداية جيدة. جرّب محاكاة قصيرة لتثبيت الاستدعاء تحت الضغط.',href:'#exam'}};
  const unitMetrics=unit=>{const ids=unit.qcmIds||[];const questions=D.qcm.filter(q=>ids.includes(q.id));const histories=questions.map(q=>state.qcmHistory[q.id]||{attempts:0,correct:0});const attempts=histories.reduce((sum,h)=>sum+h.attempts,0);const correct=histories.reduce((sum,h)=>sum+h.correct,0);const answered=histories.filter(h=>h.attempts>0).length;const caseId=(unit.situationIds||[])[0];const cards=D.flashcards.filter(card=>(unit.cardIds||[]).includes(card.id));return {questions,attempts,correct,answered,coverage:questions.length?answered/questions.length:0,accuracy:attempts?correct/attempts:null,lessonDone:state.readLessons.includes(unit.id),quizDone:questions.length>0&&answered===questions.length,caseId,caseDone:caseId!==undefined&&state.situationAnswers[caseId]!==undefined,cards,cardsDone:cards.length>0&&cards.every(card=>Boolean(state.flashSchedule[card.id]?.nextReviewAt))}};
  const focusUnit=()=>{const units=D.deepUnits||[];const active=units.find(unit=>unit.id===state.activeUnitId);if(active&&state.activeUnitDate===dayKey()){const m=unitMetrics(active);if([m.lessonDone,m.quizDone,m.caseDone,m.cardsDone].filter(Boolean).length<4)return active}const next=[...units].map((unit,index)=>{const m=unitMetrics(unit);const complete=[m.lessonDone,m.quizDone,m.caseDone,m.cardsDone].filter(Boolean).length===4;const known=m.accuracy??.5;const priority=.7*(1-known)+.3*(1-m.coverage);return {unit,index,complete,priority}}).sort((a,b)=>(a.complete===b.complete?0:a.complete?1:-1)||(b.priority-a.priority)||a.index-b.index)[0]?.unit||units[0];if(next){state.activeUnitId=next.id;state.activeUnitDate=dayKey();save()}return next};
  const flashDeck=()=>{const now=Date.now();const rank=card=>{const due=state.flashSchedule[card.id]?.nextReviewAt;if(!due)return 1;return due<=now?0:2};return [...D.flashcards].sort((a,b)=>{const ra=rank(a),rb=rank(b);if(ra!==rb)return ra-rb;if(ra===0)return (state.flashSchedule[a.id]?.nextReviewAt||0)-(state.flashSchedule[b.id]?.nextReviewAt||0);return 0})};
  const streak=()=>{let n=0;let d=new Date();while(state.studyDays.includes(d.toISOString().slice(0,10))){n++;d.setDate(d.getDate()-1)}return n};
  function home(){const stats=qcmStats();const rec=recommendation();const unit=focusUnit();const unitStats=unitMetrics(unit);const dueCards=Object.values(state.flashSchedule).filter(x=>x.nextReviewAt&&x.nextReviewAt<=Date.now()).length;return `<div class="page"><section class="hero"><div class="hero-inner"><p class="eyebrow" style="color:#f0c4a9">جلسة مراجعة هادئة</p><h1>افهم الفكرة، ثم حوّلها إلى جواب.</h1><p>بنك أسئلة، وضعيات من القسم، وبطاقات ذكية لمساعدتك على الاستعداد لمباراة التعليم بثقة.</p><div class="hero-actions"><a class="btn btn-primary" href="#qcm">ابدأ جلسة مراجعة <span>←</span></a><a class="btn btn-outline" href="#about">كيف يعمل المرشد؟</a></div></div></section><div class="quick-stats"><div class="stat-card"><strong>${stats.mastery}%</strong><span>إتقان الأسئلة</span></div><div class="stat-card"><strong>${stats.answered}</strong><span>سؤالًا تمت إجابته</span></div><div class="stat-card"><strong>${streak()}</strong><span>أيام متتالية</span></div><div class="stat-card"><strong>${D.flashcards.length}</strong><span>بطاقة مراجعة</span></div></div><section class="study-teaser"><div><p class="eyebrow">مسار اليوم · مراجعة موجهة</p><h2>${esc(unit.title)}</h2><p>درس معمق، أسئلة مرتبطة، وضعية مهنية، ثم بطاقاتك المستحقة${dueCards?` · ${dueCards} بطاقة اليوم`:''} · ${unitStats.answered}/${unitStats.questions.length} أسئلة مجابة.</p></div><a class="btn btn-primary" href="#path">ابدأ المسار ←</a></section><div class="page-columns"><div><div class="section-title"><div><h2>أين تركز الآن؟</h2><p>توصية صغيرة مبنية على نشاطك المحلي</p></div></div><div class="panel recommendation"><div class="recommendation-icon">↗</div><div><h3>${rec.title}</h3><p>${rec.text}</p><a class="text-link" href="${rec.href}">ابدأ الآن ←</a></div></div><div class="section-title"><div><h2>مسارات المراجعة</h2><p>اختر طريقة تناسب وقتك اليوم</p></div></div><div class="action-grid"><a class="action-card" href="#qcm"><span class="action-icon">?</span><div><h3>أسئلة QCM</h3><p>اختبر فهمك مع تفسير فوري.</p></div></a><a class="action-card" href="#situations"><span class="action-icon">◈</span><div><h3>وضعيات مهنية</h3><p>فكر كمدرس داخل القسم.</p></div></a><a class="action-card" href="#flashcards"><span class="action-icon">▱</span><div><h3>بطاقات المفاهيم</h3><p>راجع بتكرار متباعد.</p></div></a><a class="action-card" href="#exam"><span class="action-icon">◷</span><div><h3>محاكاة الامتحان</h3><p>25 سؤالًا في 60 دقيقة.</p></div></a><a class="action-card" href="#theories"><span class="action-icon">◎</span><div><h3>شبكة النظريات</h3><p>اربط السؤال بصاحبه ومفاهيمه.</p></div></a><a class="action-card" href="#inclusive"><span class="action-icon">↗</span><div><h3>التربية الدامجة</h3><p>درس ومرجعيات رسمية.</p></div></a><a class="action-card" href="#resources"><span class="action-icon">▣</span><div><h3>مكتبة الموارد</h3><p>دلائل ونصوص موثوقة.</p></div></a><a class="action-card deep-action" href="#lessons"><span class="action-icon">↗</span><div><h3>دروس معمقة</h3><p>شرح المحاور الرسمية بالأمثلة.</p></div></a></div></div><aside><div class="section-title"><div><h2>تقدمك</h2><p>يتحفظ على هذا الهاتف فقط</p></div><a class="text-link" href="#progress">التفاصيل</a></div><div class="panel"><div class="panel-head"><div><h3>الإتقان العام</h3><p>${stats.correct} إجابة صحيحة من ${stats.answered}</p></div><strong style="color:var(--accent)">${stats.mastery}%</strong></div><div class="progress-line"><span style="width:${stats.mastery}%"></span></div><div class="progress-label"><span>واصل بخطوة واحدة اليوم</span><strong>${streak()?`اليوم ${streak()} من السلسلة`:'ابدأ سلسلتك'}</strong></div></div><div class="section-title"><div><h2>آخر نشاط</h2></div></div><div class="panel"><div class="activity-list">${state.activities.length?state.activities.slice(0,4).map(a=>`<div class="activity"><span class="activity-dot"></span><div><strong>${a.label}</strong><span>${a.detail||'جلسة مراجعة'} · ${a.time}</span></div></div>`).join(''):'<div class="empty">ستظهر هنا خطواتك الأولى. ابدأ بسؤال أو بطاقة.</div>'}</div></div></aside></div><p class="footer-note">المحتوى استرشادي للمراجعة. طابقه دائمًا مع الإطار المرجعي والتوجيهات الرسمية المعتمدة.</p></div>`}
  function qcm(){const pool=qcmPool();if(state.qcmIndex>=pool.length)state.qcmIndex=0;const q=pool[state.qcmIndex];return `<div class="page">${pageHead('بنك المراجعة','أسئلة QCM','أجب، اقرأ لماذا، ثم انتقل بخطوة واضحة.',`<button class="btn btn-outline focus-exit" id="exit-focus">الخروج من التركيز</button>`)}<div class="filters"><div class="search-box"><span>⌕</span><input id="qcm-search" type="search" value="${esc(state.qcmFilters.query)}" placeholder="ابحث في السؤال أو المفهوم" aria-label="البحث في الأسئلة"></div><div class="filter-row">${[['all','كل المجالات'],...Object.entries(D.domainNames)].map(([id,label])=>`<button class="chip ${state.qcmFilters.domain===id?'active':''}" data-filter="domain" data-value="${id}">${label}</button>`).join('')}</div><div class="filter-row"><button class="chip ${state.qcmFilters.difficulty==='all'?'active':''}" data-filter="difficulty" data-value="all">كل الصعوبات</button>${D.levelNames.map(x=>`<button class="chip ${state.qcmFilters.difficulty===x?'active':''}" data-filter="difficulty" data-value="${x}">${x}</button>`).join('')}<button class="chip ${state.qcmFilters.status==='all'?'active':''}" data-filter="status" data-value="all">كل الحالات</button><button class="chip ${state.qcmFilters.status==='wrong'?'active':''}" data-filter="status" data-value="wrong">أخطأت</button><button class="chip ${state.qcmFilters.status==='correct'?'active':''}" data-filter="status" data-value="correct">أجبت صحيحًا</button></div></div>${q?questionCard(q,pool):'<div class="empty">لا توجد أسئلة بهذا الاختيار. جرّب إزالة فلتر واحد.</div>'}</div>`}
  function questionCard(q,pool){const picked=state.qcmAnswers[q.id];const answered=picked!==undefined;return `<section class="question-card"><div class="session-top"><span class="question-domain">${domainName(q.domain)} · ${q.difficulty}</span><span class="session-count"><bdi dir="ltr"><strong>${state.qcmIndex+1}</strong> / ${pool.length}</bdi></span></div><div class="progress-line"><span style="width:${percent(state.qcmIndex+1,pool.length)}%"></span></div><h2>${q.question}</h2><div class="option-list">${q.options.map((o,i)=>`<button class="option ${answered&&i===q.answer?'correct':''} ${answered&&i===picked&&picked!==q.answer?'wrong':''}" data-qcm-option="${i}" aria-pressed="${answered&&i===picked}" ${answered?'disabled':''}>${o}</button>`).join('')}</div>${answered?`<div class="feedback"><strong>${picked===q.answer?'إجابة موفقة.':'راجع هذه الفكرة بهدوء.'}</strong><p>${q.explanation}</p><span class="concept-tag">المفتاح: ${q.concept}</span><a class="theory-link" href="#theory-${q.theory_ids?.[0]||'bloom'}">راجع النظرية المرتبطة ←</a></div>`:''}<div class="session-actions">${answered?`<button class="btn btn-primary" id="next-qcm">${state.qcmIndex===pool.length-1?'ابدأ من جديد':'السؤال التالي'} ←</button>`:'<span class="muted small">اختر إجابة واحدة لترى التفسير.</span>'}<button class="btn btn-outline" id="start-focus">◌ تركيز</button></div><div class="question-grid">${pool.slice(0,Math.min(pool.length,20)).map((x,i)=>`<button class="question-dot ${i===state.qcmIndex?'current':''} ${qcmStatus(x)==='correct'?'correct':''} ${qcmStatus(x)==='wrong'?'wrong':''}" data-qcm-jump="${i}" aria-label="السؤال ${i+1}" aria-current="${i===state.qcmIndex?'step':'false'}">${i+1}</button>`).join('')}</div></section>`}
  function situations(){const s=D.situations[state.situationIndex%D.situations.length];const picked=state.situationAnswers[s.id];return `<div class="page">${pageHead('مختبر القسم','وضعيات مهنية','اختر الإجراء الأنسب، ثم اقرأ التحليل كما لو كنت أمام اللجنة.')}<section class="situation-card"><div class="situation-meta"><span>${s.domain}</span><span>${state.situationIndex+1} / ${D.situations.length}</span></div><h2>${s.title}</h2><div class="scenario">${s.scenario}</div><div class="option-list">${s.options.map((o,i)=>`<button class="option ${picked!==undefined&&i===s.answer?'correct':''} ${picked!==undefined&&i===picked&&picked!==s.answer?'wrong':''}" data-sit-option="${i}" ${picked!==undefined?'disabled':''}>${o}</button>`).join('')}</div>${picked!==undefined?`<div class="analysis"><h3>التحليل التربوي</h3><p>${s.analysis}</p><p><strong>النظرية المرتبطة:</strong> ${s.theory}</p><p><strong>لماذا البدائل أقل مناسبة؟</strong> ${s.alternatives}</p><p><strong>تأمل المدرس:</strong> ${s.reflection}</p></div><button class="btn btn-primary" id="next-situation" style="margin-top:14px">وضعية تالية ←</button>`:'<p class="muted small" style="margin-top:13px">لا تبحث عن العبارة المثالية؛ ابحث عن القرار الذي يحمي التعلم ويستند إلى تشخيص.</p>'}</section><div class="section-title"><div><h2>خريطة الوضعيات</h2><p>اختر سيناريو آخر مباشرة</p></div></div><div class="question-grid">${D.situations.map((x,i)=>`<button class="question-dot ${i===state.situationIndex?'current':''} ${state.situationAnswers[x.id]!==undefined?'correct':''}" data-sit-jump="${i}" aria-label="الوضعية ${i+1}">${i+1}</button>`).join('')}</div></div>`}
  function flashcards(){const deck=flashDeck();const card=deck[state.flashIndex%deck.length];const rating=state.flashRatings[card.id];const mastered=Object.values(state.flashRatings).filter(x=>x==='mastered').length;return `<div class="page"><div class="page-head"><div><p class="eyebrow">ذاكرة قصيرة، أثر طويل</p><h1>بطاقات المفاهيم</h1><p>اقلب البطاقة، استدع الفكرة، ثم أخبر المرشد بمستوى ثقتك.</p></div><span class="question-domain">${mastered} / ${D.flashcards.length} أتقنتها · ${Object.values(state.flashSchedule).filter(x=>x.nextReviewAt&&x.nextReviewAt<=Date.now()).length} مستحقة</span></div><div class="panel"><div class="deck-meter"><span>تقدم هذا deck</span><strong>${percent(mastered,D.flashcards.length)}%</strong></div><div class="progress-line" style="margin-top:8px"><span style="width:${percent(mastered,D.flashcards.length)}%"></span></div></div><div class="flash-layout" style="margin-top:13px"><div class="flashcard-scene"><div class="flashcard ${state.flashFlipped?'flipped':''}" data-flip><div class="flash-face"><span class="flash-label">المفهوم · اضغط للقلب</span><h2>${card.front}</h2><span class="muted small" style="margin-top:15px">فكّر في التعريف قبل أن تقلبها</span></div><div class="flash-face back"><span class="flash-label">التعريف والمثال</span><p>${card.back}</p><p style="margin-top:15px"><strong style="color:var(--accent)">مثال:</strong> ${card.example}</p><span class="muted small" style="margin-top:auto">اضغط للعودة إلى الوجه الأول</span></div></div></div>${state.flashFlipped?`<div class="rating-actions"><button class="btn btn-outline" data-rate="tomorrow">راجع غدًا</button><button class="btn btn-secondary" data-rate="today">راجع اليوم</button><button class="btn btn-primary" data-rate="mastered">أتقنتها</button></div>`:'<p class="muted small" style="text-align:center">القلب ليس اختبارًا؛ هو لحظة استدعاء نشط.</p>'}<div class="session-actions"><button class="btn btn-outline" id="prev-card">← السابقة</button><span class="muted small"><bdi dir="ltr">${state.flashIndex+1} / ${deck.length}</bdi>${rating?` · ${rating==='mastered'?'متقنة':'مجدولة'}`:''}</span><button class="btn btn-primary" id="next-card">التالية →</button></div></div></div>`}
  function startExam(){const count=Number(document.getElementById('exam-count')?.value||state.examSetup.count||25);const minutes=Number(document.getElementById('exam-minutes')?.value||state.examSetup.minutes||60);const domain=document.getElementById('exam-domain')?.value||state.examSetup.domain||'all';state.examSetup={count,minutes,domain};const source=domain==='all'?D.qcm:D.qcm.filter(q=>q.domain===domain);const pool=[...source];for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}const shuffled=pool.slice(0,count);if(shuffled.length<count)toast(`المجال المحدد يضم ${shuffled.length} أسئلة فقط؛ ستبدأ بها كاملة.`);const now=Date.now();state.exam={questions:shuffled.map(q=>q.id),answers:{},flags:[],current:0,startedAt:now,endsAt:now+minutes*60*1000,finished:false};recordActivity('بدأت محاكاة الامتحان',`${shuffled.length} سؤالًا · ${minutes} دقيقة`);save();render()}
  function exam(){if(!state.exam)return `<div class="page"><div class="panel exam-setup"><div class="exam-icon">◷</div><p class="eyebrow" style="justify-content:center">تدريب تحت الضغط</p><h2>محاكاة الامتحان</h2><p>اختر حجم الجلسة ووقتها ومجالها، ثم ابدأ محاكاة قابلة للحفظ على هذا الهاتف.</p><div class="exam-setup-fields"><label>عدد الأسئلة<select class="select" id="exam-count"><option value="15" ${state.examSetup.count===15?'selected':''}>15 سؤالًا</option><option value="25" ${state.examSetup.count===25?'selected':''}>25 سؤالًا</option><option value="40" ${state.examSetup.count===40?'selected':''}>40 سؤالًا</option></select></label><label>المدة<select class="select" id="exam-minutes"><option value="30" ${state.examSetup.minutes===30?'selected':''}>30 دقيقة</option><option value="60" ${state.examSetup.minutes===60?'selected':''}>60 دقيقة</option><option value="90" ${state.examSetup.minutes===90?'selected':''}>90 دقيقة</option></select></label><label>المجال<select class="select" id="exam-domain"><option value="all" ${state.examSetup.domain==='all'?'selected':''}>كل المجالات</option>${Object.entries(D.domainNames).map(([id,name])=>`<option value="${id}" ${state.examSetup.domain===id?'selected':''}>${name}</option>`).join('')}</select></label></div><button class="btn btn-primary" id="start-exam">ابدأ المحاكاة</button></div><div class="section-title"><div><h2>قبل أن تبدأ</h2><p>جلسة واحدة بلا تشتيت</p></div></div><div class="panel"><ul class="bullet-list"><li>لا توجد إجابة صحيحة حتى تضغط على تسليم.</li><li>يمكنك تعليم أي سؤال والعودة إليه من الشبكة.</li><li>بعد النهاية سترى نقاط الضعف حسب المجال.</li></ul></div></div>`;if(state.exam.finished)return examResult();const left=Math.max(0,state.exam.endsAt-Date.now());const q=D.qcm.find(x=>x.id===state.exam.questions[state.exam.current]);const picked=state.exam.answers[q.id];return `<div class="page">${pageHead('محاكاة الامتحان',`جلسة ${Math.round((state.exam.endsAt-state.exam.startedAt)/60000)} دقيقة`,'أجب بهدوء. يمكنك التنقل وتعليم السؤال للمراجعة.') }<div class="exam-layout"><section class="question-card"><div class="exam-top"><span class="question-domain">${domainName(q.domain)} · ${q.difficulty}</span><span class="timer ${left<5*60*1000?'urgent':''}" id="exam-timer">${formatTime(left)}</span></div><h2>${q.question}</h2><div class="option-list">${q.options.map((o,i)=>`<button class="option ${picked!==undefined&&i===q.answer&&state.exam.finished?'correct':''} ${picked!==undefined&&i===picked&&!state.exam.finished?'selected':''}" data-exam-option="${i}">${o}</button>`).join('')}</div><div class="session-actions"><button class="flag-button ${state.exam.flags.includes(q.id)?'active':''}" id="flag-exam">${state.exam.flags.includes(q.id)?'★ معلّم للمراجعة':'☆ علّم للمراجعة'}</button><button class="btn btn-primary" id="next-exam">${state.exam.current===state.exam.questions.length-1?'مراجعة التسليم':'السؤال التالي'} ←</button></div></section><aside><div class="panel"><div class="panel-head"><div><h3>خريطة الأسئلة</h3><p>${Object.keys(state.exam.answers).length} تمت الإجابة</p></div></div><div class="question-grid">${state.exam.questions.map((id,i)=>`<button class="question-dot ${i===state.exam.current?'current':''} ${state.exam.answers[id]!==undefined?'correct':''} ${state.exam.flags.includes(id)?'wrong':''}" data-exam-jump="${i}" aria-label="السؤال ${i+1}">${i+1}</button>`).join('')}</div><button class="btn btn-primary" id="submit-exam" style="width:100%;margin-top:16px">تسليم الإجابات</button></div><div class="panel"><p class="muted small" style="margin:0">السؤال المعلّم ليس خاطئًا؛ هو فقط يحتاج عودة قبل التسليم.</p></div></aside></div></div>`}
  function formatTime(ms){const s=Math.max(0,Math.floor(ms/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
  function examResult(){const qs=state.exam.questions.map(id=>D.qcm.find(q=>q.id===id));const score=qs.filter(q=>state.exam.answers[q.id]===q.answer).length;const scorePercent=percent(score,qs.length);const domains=[...new Set(qs.map(q=>q.domain))].map(id=>{const group=qs.filter(q=>q.domain===id);const ok=group.filter(q=>state.exam.answers[q.id]===q.answer).length;return {id,ok,total:group.length}});return `<div class="page">${pageHead('نتيجة المحاكاة','ماذا تعلمت من الجلسة؟','النتيجة ليست حكمًا؛ إنها خريطة للخطوة التالية.')}<div class="result-hero"><strong>${score} / ${qs.length}</strong><p>${scorePercent>=80?'أداء قوي جدًا. حافظ على تنويع المجالات.':scorePercent>=56?'بداية جيدة. راجع تفسير الأخطاء قبل جولة جديدة.':'استعمل النتيجة لتحديد مجال واحد تبدأ به اليوم.'}</p></div><div class="section-title"><div><h2>الأداء حسب المجال</h2><p>كل شريط يروي قصة صغيرة</p></div></div><div class="panel domain-bars">${domains.map(x=>`<div class="domain-row"><span>${domainName(x.id)}</span><div class="progress-line"><span style="width:${percent(x.ok,x.total)}%"></span></div><strong>${x.ok}/${x.total}</strong></div>`).join('')}</div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>نقاط الضعف</h3><p>أسئلة أخطأت فيها ويمكنك إعادة تعلمها</p></div></div><div class="list">${qs.filter(q=>state.exam.answers[q.id]!==q.answer).slice(0,5).map(q=>`<div class="activity"><span class="activity-dot"></span><div><strong>${q.concept}</strong><span>${domainName(q.domain)} · راجع التفسير في بنك الأسئلة.</span></div></div>`).join('')||'<div class="empty">لا توجد أخطاء في هذه الجولة. ممتاز.</div>'}</div></div><div class="session-actions"><button class="btn btn-primary" id="restart-exam">محاكاة جديدة</button><a class="btn btn-outline" href="#progress">لوحة التقدم</a></div></div>`}
  function progress(){const stats=qcmStats();const domainRows=Object.keys(D.domainNames).map(id=>{const qs=D.qcm.filter(q=>q.domain===id);const ans=qs.filter(q=>state.qcmAnswers[q.id]!==undefined);const ok=ans.filter(q=>state.qcmAnswers[q.id]===q.answer).length;return {id,total:qs.length,answered:ans.length,ok,score:percent(ok,ans.length)}});return `<div class="page">${pageHead('صورتك الكبيرة','لوحة التقدم','اعرف ما أتقنته وما يستحق جلسة قصيرة إضافية.')}<div class="metric-grid"><div class="metric"><strong>${stats.mastery}%</strong><span>إتقان عام</span></div><div class="metric"><strong>${stats.accuracy}%</strong><span>دقة الإجابات</span></div><div class="metric"><strong>${streak()}</strong><span>سلسلة أيام</span></div><div class="metric"><strong>${Object.keys(state.flashRatings).length}</strong><span>بطاقات لُوحظت</span></div></div><div class="section-title"><div><h2>التقدم حسب المجال</h2><p>المجال الفارغ يحتاج أول جلسة، لا حكمًا مسبقًا</p></div></div><div class="panel domain-bars">${domainRows.map(x=>`<div class="domain-row"><span>${domainName(x.id)}</span><div class="progress-line"><span style="width:${x.score}%"></span></div><strong>${x.answered?`${x.score}%`:'—'}</strong></div>`).join('')}</div><div class="page-columns"><div><div class="section-title"><div><h2>آخر نشاط</h2><p>أثر جلساتك القصيرة</p></div></div><div class="panel"><div class="activity-list">${state.activities.length?state.activities.map(a=>`<div class="activity"><span class="activity-dot"></span><div><strong>${a.label}</strong><span>${a.detail||''} · ${a.time}</span></div></div>`).join(''):'<div class="empty">لا نشاط بعد. ابدأ من بنك الأسئلة.</div>'}</div></div></div><div><div class="section-title"><div><h2>إشارة اليوم</h2></div></div><div class="panel recommendation"><div class="recommendation-icon">✓</div><div><h3>${recommendation().title}</h3><p>${recommendation().text}</p></div></div></div></div></div>`}
  function about(){return `<div class="page">${pageHead('عن المرشد','مراجعة تفهمك قبل أن تختبرك','مرشد التربية مساحة مراجعة استرشادية للمترشحين لمباراة التعليم في علوم التربية.')}<div class="panel"><h2 style="margin-top:0;font-size:18px">منهجية المرشد</h2><p class="muted" style="font-size:13px">نحن لا نضع التعريفات في عزلة؛ كل مفهوم يرتبط بسؤال أو مثال من القسم أو قرار تربوي. استخدم الجلسات القصيرة، اقرأ التفسير بعد كل إجابة، ثم تحدث بصوت عال كما لو كنت أمام اللجنة.</p><div class="action-grid" style="margin-top:15px"><div class="action-card"><span class="action-icon">01</span><div><h3>افهم</h3><p>مخطط أو بطاقة يحدد الفكرة.</p></div></div><div class="action-card"><span class="action-icon">02</span><div><h3>طبّق</h3><p>سؤال أو وضعية يختبر النقل.</p></div></div><div class="action-card"><span class="action-icon">03</span><div><h3>فسّر</h3><p>لماذا هذا القرار أنسب؟</p></div></div><div class="action-card"><span class="action-icon">04</span><div><h3>تتبّع</h3><p>تقدم محلي يساعدك على الاختيار.</p></div></div></div></div><div class="note" style="margin-top:14px"><strong>تنبيه:</strong> المحتوى استرشادي. راجع الإطار المرجعي والوثائق الرسمية الخاصة بدورتك، ولا تعتبر البطاقات بديلًا عن التكوين أو التوجيهات المعتمدة.</div></div>`}
  function inclusiveQuiz(){const q=D.inclusive.quiz;if(state.inclusiveQuizIndex>=q.length)return `<div class="panel quiz-finished"><p class="eyebrow">النتيجة</p><h2>أتممت اختبار التربية الدامجة</h2><div class="result-hero" style="margin-top:12px"><strong>${state.inclusiveQuizScore} / ${q.length}</strong><p>${state.inclusiveQuizScore>=4?'استيعاب ممتاز للمرجعيات والمفاهيم.':'راجع المرجعيات ثم جرّب من جديد.'}</p></div><button class="btn btn-primary" id="restart-inclusive-quiz" style="margin-top:13px">إعادة الاختبار</button></div>`;const x=q[state.inclusiveQuizIndex];return `<div class="panel"><p class="eyebrow">اختبار قصير · ${state.inclusiveQuizIndex+1}/${q.length}</p><h2>${x.question}</h2><div class="option-list">${x.options.map((o,i)=>`<button class="option ${state.inclusiveQuizPicked===null?'':i===x.answer?'correct':i===state.inclusiveQuizPicked?'wrong':''}" data-inclusive-answer="${i}" ${state.inclusiveQuizPicked===null?'':'disabled'}>${o}</button>`).join('')}</div>${state.inclusiveQuizPicked!==null?`<div class="feedback"><strong>${state.inclusiveQuizPicked===x.answer?'إجابة صحيحة.':'راجع الإجابة.'}</strong><p>${x.explain}</p></div><button class="btn btn-primary" id="next-inclusive-quiz" style="margin-top:12px">${state.inclusiveQuizIndex===q.length-1?'اعرض النتيجة':'السؤال التالي'} ←</button>`:''}</div>`}
  function inclusive(){const x=D.inclusive;const i=Math.max(0,Math.min(state.inclusivePillar,x.pillars.length-1));const pillar=x.pillars[i];return `<div class="page">${pageHead('درس مركز','التربية الدامجة',x.subtitle,`<a class="btn btn-outline" href="#resources">الموارد الرسمية</a>`)}<section class="hero inclusive-hero"><div class="hero-inner"><p class="eyebrow" style="color:#f0c4a9">فهم · تكييف · مواكبة</p><h1>مدرسة تستقبل الجميع وتزيل الحواجز أمام التعلم.</h1><p>${x.intro}</p></div></section><div class="section-title"><div><h2>الأعمدة الأربعة</h2><p>اضغط على أي عمود لفتح تبويبه، أو انتقل بالتتابع.</p></div><span class="question-domain"><bdi dir="ltr">${i+1} / ${x.pillars.length}</bdi></span></div><div class="pillar-tabs" role="tablist" aria-label="أعمدة التربية الدامجة">${x.pillars.map((p,n)=>`<button class="pillar-tab ${n===i?'active':''}" role="tab" aria-selected="${n===i}" data-pillar="${n}"><span>0${n+1}</span><strong>${p[0]}</strong></button>`).join('')}</div><section class="pillar-panel" role="tabpanel"><span class="eyebrow">التبويب ${i+1} · ${pillar[0]}</span><h2>${pillar[0]}</h2><p>${pillar[1]}</p><div class="pillar-progress"><span style="width:${((i+1)/x.pillars.length)*100}%"></span></div><button class="btn btn-primary" id="next-pillar">${i===x.pillars.length-1?'العودة إلى أول تبويب':'التبويب التالي'} <span>←</span></button></section><div class="section-title"><div><h2>من الفكرة إلى الممارسة</h2><p>مسار قصير داخل المؤسسة</p></div></div><div class="panel">${x.steps.map((s,n)=>`<div class="activity"><span class="activity-dot"></span><div><strong>${n+1}. ${s[0]}</strong><span>${s[1]}</span></div></div>`).join('')}</div><div class="section-title"><div><h2>مرجعيات ينبغي حفظها</h2><p>روابط رسمية واستطرادية</p></div></div><div class="list">${x.references.map(r=>`<a class="list-card" href="${r[2]}" target="_blank" rel="noreferrer"><span class="card-number">↗</span><div><h3>${r[0]}</h3><p>${r[1]}</p></div></a>`).join('')}</div><div class="section-title"><div><h2>اختبر فهمك</h2><p>5 أسئلة حول التربية الدامجة ومرجعياتها</p></div></div>${inclusiveQuiz()}<div class="note" style="margin-top:14px"><strong>مفتاح الجواب:</strong> ${x.quote}</div></div>`}
  function resources(){const types=['all',...new Set(D.resources.map(r=>r.type))];const shown=D.resources.filter(r=>(state.resourceFilter==='all'||r.type===state.resourceFilter)&&`${r.title} ${r.description} ${r.tag}`.toLowerCase().includes(state.resourceSearch.toLowerCase()));return `<div class="page">${pageHead('مرجعك السريع','مكتبة الموارد الرقمية','أدلة عملية ومرجعيات موثوقة تساعدك على تنزيل التربية الدامجة.') }<section class="panel resources-hero"><p class="eyebrow">روابط منتقاة</p><h2>اقرأ، خطط، وواكب.</h2><p class="muted">ابحث حسب العنوان أو صفِّ الموارد حسب نوعها. افتح البطاقة للتحميل أو القراءة من المصدر.</p></section><div class="filters"><div class="search-box"><span>⌕</span><input id="resource-search" type="search" value="${esc(state.resourceSearch)}" placeholder="ابحث عن دليل، قانون، خارطة..." aria-label="البحث في الموارد"></div><div class="filter-row">${types.map(t=>`<button class="chip ${state.resourceFilter===t?'active':''}" data-resource-filter="${esc(t)}">${t==='all'?'الكل':t}</button>`).join('')}</div></div><div class="list">${shown.length?shown.map(r=>`<a class="list-card resource-card" href="${r.url}" target="_blank" rel="noreferrer"><span class="card-number">▣</span><div><span class="source">${r.type} · ${r.source}</span><h3>${r.title}</h3><p>${r.description}</p><strong class="text-link">${r.action} ↗</strong></div></a>`).join(''):'<div class="empty">لم نعثر على مورد بهذا البحث.</div>'}</div><div class="note" style="margin-top:14px"><strong>ملاحظة:</strong> تحقق من آخر نسخة منشورة لدى الجهة الرسمية عند إعداد ملف أو جواب مهني.</div></div>`}
  function studyPath(){const unit=focusUnit();const m=unitMetrics(unit);const done=[m.lessonDone,m.quizDone,m.caseDone,m.cardsDone].filter(Boolean).length;const completion=percent(done,4);const unitCards=m.cards.length;return `<div class="page">${pageHead('خطة مراجعة ذكية','مسار اليوم',`مسار قصير يتغير حسب إجاباتك السابقة. ركّز الآن على «${esc(unit.title)}».`)}<section class="path-overview"><div><p class="eyebrow">مجال يحتاج عناية</p><h2>${esc(unit.title)}</h2><p>${esc(unit.subtitle)}</p></div><div class="path-score"><strong>${completion}%</strong><span>تقدم المسار</span></div><div class="path-progress"><span style="width:${completion}%"></span></div><p class="path-meta">${m.attempts?`دقة الأسئلة المرتبطة ${percent(m.correct,m.attempts)}%`:'لم تختبر أسئلة هذا المحور بعد'} · ${m.questions.length} أسئلة · ${unitCards} بطاقات · جلسة تقديرية 15–20 دقيقة</p></section><div class="section-title"><div><h2>حلقة تعلم متكاملة</h2><p>افهم، استرجع، طبّق، ثم ثبّت المعلومة.</p></div></div><div class="path-steps"><article class="path-step ${m.lessonDone?'done':''}"><span class="path-step-number">01</span><div><span class="path-step-label">افهم · 5 دقائق</span><h3>ابدأ بالدرس المعمق</h3><p>اقرأ الفكرة المركزية والفروق، ثم لاحظ الأخطاء الشائعة قبل الحفظ.</p><a class="btn btn-outline" href="#lesson-${unit.id}">${m.lessonDone?'أعد فتح الدرس':'افتح الدرس'} ←</a><span class="path-status">${m.lessonDone?'تمت الزيارة':'الخطوة الأولى'}</span></div></article><article class="path-step ${m.quizDone?'done':''}"><span class="path-step-number">02</span><div><span class="path-step-label">استرجع · 5 دقائق</span><h3>اختبر فهمك في ${m.questions.length} أسئلة</h3><p>الأسئلة مربوطة مباشرة بالمحور؛ اقرأ التفسير بعد كل إجابة.</p><button class="btn btn-outline" type="button" data-path-action="quiz" data-unit="${unit.id}">ابدأ أسئلة المحور ←</button><span class="path-status">${m.quizDone?'أجبت عن جميع الأسئلة':`${m.answered} / ${m.questions.length} تمت الإجابة`}</span></div></article><article class="path-step ${m.caseDone?'done':''}"><span class="path-step-number">03</span><div><span class="path-step-label">طبّق · 5 دقائق</span><h3>انقل الفكرة إلى وضعية مهنية</h3><p>اختر قرارًا تربويًا، ثم اقرأ التحليل والبدائل والتأمل المقترح.</p><button class="btn btn-outline" type="button" data-path-action="situation" data-unit="${unit.id}">${m.caseDone?'راجع الوضعية':'حل الوضعية'} ←</button><span class="path-status">${m.caseDone?'أكملت المحاولة':'محاولة تطبيق واحدة'}</span></div></article><article class="path-step ${m.cardsDone?'done':''}"><span class="path-step-number">04</span><div><span class="path-step-label">ثبّت · 3 دقائق</span><h3>راجع بطاقات المحور</h3><p>استدعِ التعريف والمثال قبل قلب البطاقة؛ المستحقة تظهر أولًا تلقائيًا.</p><button class="btn btn-outline" type="button" data-path-action="flashcards" data-unit="${unit.id}">افتح ${unitCards} بطاقات ←</button><span class="path-status">${m.cardsDone?'تمت مراجعة البطاقات':`بطاقات مرتبطة: ${unitCards}`}</span></div></article></div><div class="session-actions"><a class="btn btn-primary" href="#resources">افتح مكتبة الموارد</a><a class="btn btn-outline" href="#progress">تابع تقدمك</a></div><div class="note"><strong>خصوصيتك:</strong> يختار المرشد المحور اعتمادًا على سجل الإجابات المحفوظ على هذا الجهاز فقط؛ لا يرسل نتائجك إلى خادم.</div></div>`}
  function lessons(){const units=D.deepUnits||[];return `<div class="page">${pageHead('المحتوى المعمق','دروس علوم التربية','اقرأ الفكرة من أصلها، ثم شاهد كيف تتحول إلى قرار داخل القسم.')}<div class="deep-map"><div><span class="eyebrow">خريطة المباراة · دورة 2026</span><h2>ستة محاور، لا ملخصات مبتورة.</h2><p>هذه المساحة تربط المحاور الرسمية بالشرح والمثال والوضعية والسؤال. ابدأ بالمجال الذي تحتاجه، ثم اختبر قدرتك على التفسير.</p></div><div class="deep-map-badge"><strong>${units.length}</strong><span>وحدات معمقة</span></div></div><div class="deep-grid">${units.map((u,i)=>`<a class="deep-card" href="#lesson-${u.id}"><span class="card-number">0${i+1}</span><div><div class="deep-card-top"><span>${u.level}</span><b>${u.weight}</b></div><h3>${u.title}</h3><p>${u.subtitle}</p><span class="text-link">افتح الدرس ←</span></div></a>`).join('')}</div><div class="note"><strong>طريقة القراءة:</strong> اقرأ الأطروحة، افهم الفروق، طبّق المثال، ثم صغ جوابًا شفويًا في دقيقة واحدة.</div><div class="source-strip"><strong>المراجع المؤسسة:</strong> ${(D.deepSources||[]).map(x=>`<a href="${x.url}" target="_blank" rel="noreferrer">${x.title} ↗</a>`).join(' · ')}</div></div>`}
  function lessonDetail(unit){if(!state.readLessons.includes(unit.id)){state.readLessons.push(unit.id);recordActivity('قرأت درسًا معمقًا',unit.title)}const linkedQ=(D.qcm||[]).filter(q=>q.id&&unit.qcmIds?.includes(q.id));const linkedS=(D.situations||[]).filter(x=>unit.situationIds?.includes(x.id));const cards=(D.flashcards||[]).filter(x=>unit.cardIds?.includes(x.id));return `<div class="page deep-detail">${backHead(unit.title,`${unit.level} · وزن المحور ${unit.weight}`)}<div class="deep-hero"><span class="eyebrow">الفكرة المركزية</span><h2>${unit.thesis}</h2><div class="deep-meta"><span>${unit.domain}</span><span>${unit.weight}</span></div></div><section class="panel deep-outcomes"><h2>ما الذي ينبغي أن تخرج به؟</h2><div class="outcome-grid">${unit.outcomes.map((x,i)=>`<div><b>0${i+1}</b><span>${x}</span></div>`).join('')}</div></section><div class="deep-sections">${unit.sections.map(x=>`<section class="info-block"><h2>${x.title}</h2><p>${x.body}</p></section>`).join('')}</div><section class="deep-split"><div class="panel"><h2>فروق يجب تثبيتها</h2><ul class="bullet-list">${unit.distinctions.map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="panel oral-answer"><span class="eyebrow">جواب شفوي في دقيقة</span><p>${unit.oral}</p></div></section><section class="panel trap-panel"><h2>أخطاء شائعة في الجواب</h2><div class="trap-list">${unit.traps.map(x=>`<span>× ${x}</span>`).join('')}</div></section><div class="section-title"><div><h2>اختبر النقل</h2><p>أسئلة ووضعيات مرتبطة بهذا المحور</p></div></div><div class="list">${linkedQ.slice(0,3).map(q=>`<a class="list-card" href="#qcm"><span class="card-number">?</span><div><h3>${q.question}</h3><p>${q.explanation}</p></div></a>`).join('')}${linkedS.slice(0,2).map(x=>`<a class="list-card" href="#situations"><span class="card-number">◈</span><div><h3>${x.title}</h3><p>${x.analysis}</p></div></a>`).join('')}</div><div class="section-title"><div><h2>بطاقات هذا المحور</h2><p>استدعاء سريع قبل المحاكاة</p></div></div><div class="deep-card-row">${cards.map(c=>`<a class="definition-card" href="#flashcards"><h3>${c.front}</h3><p>${c.back}</p></a>`).join('')}</div><div class="session-actions"><a class="btn btn-primary" href="#lessons">كل الدروس المعمقة</a><a class="btn btn-outline" href="#qcm">اختبر نفسك الآن</a></div></div>`}
  function theories(){return `<div class="page">${pageHead('خريطة المعرفة','شبكة النظريات','اربط السؤال بصاحبه ومفاهيمه بدل حفظ الأسماء في عزلة.')}<div class="list">${D.theories.map((t,i)=>`<a class="list-card" href="#theory-${t.id}"><span class="card-number">${String(i+1).padStart(2,'0')}</span><div><h3>${t.name_ar} <em class="tag">${t.proponent_ar}</em></h3><p>${t.summary_ar}</p><span class="source">${t.key_concepts.slice(0,3).join(' · ')}</span></div><span class="arrow">‹</span></a>`).join('')}</div></div>`}
  function theoryDetail(t){const questions=D.qcm.filter(q=>q.theory_ids?.includes(t.id)).slice(0,4);const situations=D.situations.filter(s=>s.theory_ids?.includes(t.id)).slice(0,3);const cards=D.flashcards.filter(c=>c.theory_ids?.includes(t.id)).slice(0,4);return `<div class="page">${backHead(t.name_ar,`${t.proponent_ar} · شبكة النظريات`)}<div class="panel"><h2 style="margin-top:0">الخلاصة</h2><p class="muted">${t.summary_ar}</p><div class="filter-row">${t.key_concepts.map(x=>`<span class="chip active">${x}</span>`).join('')}</div></div>${t.method_note_ar?`<div class="note" style="margin-top:12px"><strong>تنبيه تربوي:</strong> ${esc(t.method_note_ar)}</div>`:''}${t.references?.length?`<div class="section-title"><div><h2>للمراجعة والتوسع</h2><p>مصادر أكاديمية مفتوحة</p></div></div><div class="list">${t.references.map(reference=>`<a class="list-card" href="${esc(reference.url)}" target="_blank" rel="noreferrer"><span class="card-number">↗</span><div><h3>${esc(reference.title)}</h3><p>مرجع أكاديمي مفتوح الوصول</p></div></a>`).join('')}</div>`:''}<div class="section-title"><div><h2>أسئلة مرتبطة</h2><p>طبّق النظرية داخل بنك الأسئلة</p></div></div><div class="list">${questions.map(q=>`<a class="list-card" href="#qcm"><span class="card-number">?</span><div><h3>${q.question}</h3><p>${q.concept}</p></div></a>`).join('')||'<div class="empty">ستضاف أسئلة مرتبطة بهذه النظرية قريبًا.</div>'}</div><div class="section-title"><div><h2>بطاقات ووضعيات</h2><p>توسيع الفكرة إلى ممارسة</p></div></div><div class="list">${cards.map(c=>`<a class="list-card" href="#flashcards"><span class="card-number">▱</span><div><h3>${c.front}</h3><p>${c.back}</p></div></a>`).join('')}${situations.map(s=>`<a class="list-card" href="#situations"><span class="card-number">◈</span><div><h3>${s.title}</h3><p>${s.theory}</p></div></a>`).join('')}</div></div>`}
  function schemes(){const query=state.qcmFilters.query;const shown=D.schemes.filter(x=>!query||`${x.title} ${x.subtitle} ${x.summary}`.includes(query));return `<div class="page">${pageHead('مكتبة الفهم','المخططات الجاهزة',`${D.schemes.length} خرائط لفهم علوم التربية والديداكتيك`)}<div class="search-box" style="margin-bottom:13px"><span>⌕</span><input id="scheme-search" type="search" value="${esc(query)}" placeholder="ابحث عن مثلث، تقويم، كفاية..." aria-label="البحث في المخططات"></div><div class="list">${shown.length?shown.map((x,i)=>`<a class="list-card" href="#s-${x.id}"><span class="card-number">${String(i+1).padStart(2,'0')}</span><div><h3>${x.title}${state.readSchemes.includes(x.id)?'<em class="tag">تمت</em>':''}</h3><p>${x.subtitle}</p></div><span class="arrow">‹</span></a>`).join(''):'<div class="empty">لم نعثر على مخطط بهذا البحث.</div>'}</div></div>`}
  function schemeDetail(x){if(!state.readSchemes.includes(x.id)){state.readSchemes.push(x.id);recordActivity('راجعت مخططًا',x.title)}return `<div class="page">${backHead(x.title,x.subtitle)}<div class="chalkboard">${x.id==='triangle'?tri(x.key):`<div class="flow">${x.flow.map((s,i)=>`<div class="flow-step"><strong>${i+1}. ${s[0]}</strong><span>${s[1]}</span></div>${i<x.flow.length-1?'<div class="flow-arrow">↓</div>':''}`).join('')}</div>`}</div><section class="info-block"><h2>الفكرة في سطرين</h2><p>${x.summary}</p><ul class="bullet-list">${x.bullets.map(b=>`<li>${b}</li>`).join('')}</ul></section><div class="note"><strong>مفتاح الحفظ:</strong> ${x.key.join(' · ')}</div><section class="info-block"><h2>معلومة توسّع فهمك</h2><ul class="bullet-list">${x.facts.map(f=>`<li>${f}</li>`).join('')}</ul></section><div class="session-actions"><a class="btn btn-primary" href="#qcm">ثبّت الفكرة بسؤال</a><a class="btn btn-outline" href="#schemes">كل المخططات</a></div></div>`}
  function glossary(){const query=state.qcmFilters.query;const categories=['all',...new Set(D.terms.map(t=>t.category))];const shown=D.terms.filter(t=>(state.termCategory==='all'||t.category===state.termCategory)&&(!query||`${t.title} ${t.definition} ${t.category} ${t.source}`.toLowerCase().includes(query.toLowerCase())));return `<div class="page glossary-page">${pageHead('مفاتيح الجواب','قاموس المفاهيم','تعريف واضح، سياق مختصر، ثم طريقة تستعمل بها المصطلح في جوابك.')}<section class="glossary-intro"><div><span class="eyebrow">${D.terms.length} بطاقة معرفة</span><h2>لا تحفظ الجملة وحدها.</h2><p>ابدأ بالمعنى، اربطه بمثال من القسم، ثم استعمله لتفسير قرار تربوي. هكذا يتحول المصطلح من تعريف جامد إلى أداة تفكير.</p></div><div class="glossary-mark">Aa</div></section><div class="search-box"><span>⌕</span><input id="term-search" type="search" value="${esc(query)}" placeholder="ابحث عن مفهوم أو صاحب نظرية..." aria-label="البحث في المفاهيم"></div><div class="term-filters" role="tablist" aria-label="تصنيف المفاهيم">${categories.map(c=>`<button class="chip ${state.termCategory===c?'active':''}" data-term-category="${esc(c)}" role="tab" aria-selected="${state.termCategory===c}">${c==='all'?'كل المفاهيم':c}</button>`).join('')}</div><div class="term-grid">${shown.length?shown.map((t,i)=>`<a class="term-card" href="#t-${t.id}"><div class="term-card-head"><span class="term-index">${String(i+1).padStart(2,'0')}</span><span class="term-category">${t.category}</span></div><h3>${t.title}${state.readTerms.includes(t.id)?'<em class="tag">راجعت</em>':''}</h3><p class="term-definition">${t.definition}</p><div class="term-card-foot"><span>${t.source}</span><strong>افتح البطاقة ←</strong></div></a>`).join(''):'<div class="empty">لا توجد نتيجة بهذا البحث أو التصنيف.</div>'}</div></div>`}
  function termDetail(t){if(!state.readTerms.includes(t.id)){state.readTerms.push(t.id);recordActivity('راجعت مفهومًا',t.title)}return `<div class="page term-detail-page">${backHead('قاموس المفاهيم',`${t.category} · ${t.source}`)}<section class="term-hero"><div><span class="eyebrow">المفهوم ${t.category}</span><h1>${t.title}</h1><p>فكرة تستعملها لفهم الوضعية، لا جملة ترددها خارج السياق.</p></div><div class="term-hero-mark">Aa</div></section><section class="term-definition-panel"><span class="eyebrow">المعنى</span><p>${t.definition}</p></section><section class="term-use"><div class="section-title"><div><h2>كيف تستعمله في جوابك؟</h2><p>ثلاث حركات تجعل التعريف أكثر إقناعًا</p></div></div><div class="term-steps"><div><b>01</b><h3>عرّف</h3><p>ابدأ بالمعنى الأساسي دون حشو أو أسماء لا تخدم السؤال.</p></div><div><b>02</b><h3>اربط</h3><p>اذكر وظيفة المفهوم في التعلم أو التدريس أو التقويم.</p></div><div><b>03</b><h3>مثّل</h3><p>اختم بمشهد قصير من القسم يثبت أنك تستطيع نقله إلى الممارسة.</p></div></div></section><div class="term-example"><span class="eyebrow">جملة انتقالية مفيدة</span><p>«يظهر هذا المفهوم عمليًا عندما يختار المدرس تدخلًا يستند إلى تشخيص حاجات المتعلمين، ثم يتتبع أثره بمؤشر قابل للملاحظة.»</p></div><div class="session-actions"><a class="btn btn-primary" href="#flashcards">راجع كبطاقة</a><a class="btn btn-outline" href="#glossary">مفهوم آخر</a></div></div>`}
  function plans(){return `<div class="page">${pageHead('من الفكرة إلى الحصة','جذاذات نموذجية','نماذج استرشادية كيّفها مع السلك والمادة والكتاب المدرسي')}<div class="list">${D.plans.map(p=>`<a class="plan-card" href="#p-${p.id}"><h3>${p.title}</h3><p>${p.level}</p><div class="plan-meta"><span class="pill">${p.duration} دقيقة</span><span class="pill">${p.objective.length} أهداف</span></div></a>`).join('')}</div></div>`}
  function planDetail(p){return `<div class="page">${backHead(p.title,`${p.level} · مدة الحصة ${p.duration} دقيقة`)}<section class="info-block"><h2>الأهداف الإجرائية</h2><ul class="bullet-list">${p.objective.map(o=>`<li>${o}</li>`).join('')}</ul></section><div class="note"><strong>المكتسبات القبلية:</strong> ${p.prior}</div><section class="info-block"><h2>سير الحصة</h2><div class="panel">${p.steps.map(s=>`<div class="activity"><span class="activity-dot"></span><div><strong>${s[0]} · ${s[1]} د</strong><span>${s[2]}</span></div></div>`).join('')}</div></section><a class="btn btn-primary" href="#progress">قيّم جاهزيتك</a></div>`}
  function practice(){return `<div class="page">${pageHead('تدريب عملي','حوّل المعرفة إلى أداء','ثلاثة مسارات قصيرة تساعدك على التقدم دون تشتيت.')}<div class="action-grid"><a class="action-card" href="#qcm"><span class="action-icon">?</span><div><h3>اختبار المفاهيم</h3><p>${D.qcm.length} سؤالًا مع تفسير وتصفية.</p></div></a><a class="action-card" href="#situations"><span class="action-icon">◈</span><div><h3>وضعيات شفوية</h3><p>قرارات صفية وتحليل أمام اللجنة.</p></div></a><a class="action-card" href="#flashcards"><span class="action-icon">▱</span><div><h3>بطاقات الاستدعاء</h3><p>راجع ثم قيّم ثقتك.</p></div></a><a class="action-card" href="#exam"><span class="action-icon">◷</span><div><h3>محاكاة كاملة</h3><p>25 سؤالًا في 60 دقيقة.</p></div></a></div><div class="section-title"><div><h2>روتين 20 دقيقة</h2><p>جلسة صغيرة قابلة للتكرار</p></div></div><div class="panel"><div class="activity-list"><div class="activity"><span class="activity-dot"></span><div><strong>7 دقائق · افهم</strong><span>اقرأ مخططًا واكتب مفتاحه من الذاكرة.</span></div></div><div class="activity"><span class="activity-dot"></span><div><strong>7 دقائق · طبّق</strong><span>أجب عن سؤال أو حل وضعية قصيرة.</span></div></div><div class="activity"><span class="activity-dot"></span><div><strong>6 دقائق · تكلّم</strong><span>قدّم جوابك بصوت عال ثم سجل تعثرًا واحدًا.</span></div></div></div></div></div>`}
  function jury(){const score=state.jury.length*2;return `<div class="page">${pageHead('تأمل مهني','فحص الجذاذة','حدد المعايير التي تحققت بصدق لتحصل على نقطة أولية من 20.')}<div class="list">${D.jury.map((x,i)=>`<button class="list-card ${state.jury.includes(i)?'selected':''}" data-jury="${i}" style="text-align:right;color:var(--ink)"><span class="card-number">${state.jury.includes(i)?'✓':i+1}</span><span>${x}</span></button>`).join('')}</div><div class="result-hero" style="margin-top:14px"><strong>${score} / 20</strong><p>${score>=16?'جاهزة للعرض مع تحسينات طفيفة.':score>=12?'تحتاج إلى تحسينات قبل العرض.':'أعد بناء العناصر الأساسية ثم أعد الفحص.'}</p></div></div>`}
  function settings(){return `<div class="page">${pageHead('مساحتك','الإعدادات','تحكم في مظهر التطبيق وبيانات هذا الجهاز.')}<div class="panel"><h2 style="font-size:16px;margin-top:0">التقدم المحلي</h2><p class="muted small">يحفظ التطبيق نشاطك على هذا الهاتف فقط، ولا يرسل الإجابات إلى خادم.</p><button class="btn btn-outline" id="reset-progress">إعادة ضبط التقدم</button></div></div>`}
  let examTimer=null;
  function render(){if(examTimer){clearInterval(examTimer);examTimer=null}const h=route();let html='';if(h==='home')html=home();else if(h==='qcm')html=qcm();else if(h==='situations')html=situations();else if(h==='flashcards')html=flashcards();else if(h==='exam')html=exam();else if(h==='progress')html=progress();else if(h==='about')html=about();else if(h==='inclusive')html=inclusive();else if(h==='resources')html=resources();else if(h==='lessons')html=lessons();else if(h==='theories')html=theories();else if(h==='schemes')html=schemes();else if(h==='glossary')html=glossary();else if(h==='plans')html=plans();else if(h==='path')html=studyPath();else if(h==='practice')html=practice();else if(h==='quiz')html=qcm();else if(h==='oral')html=situations();else if(h==='jury')html=jury();else if(h==='settings')html=settings();else if(h.startsWith('s-')){const x=D.schemes.find(x=>`s-${x.id}`===h);html=x?schemeDetail(x):schemes()}else if(h.startsWith('t-')){const x=D.terms.find(x=>`t-${x.id}`===h);html=x?termDetail(x):glossary()}else if(h.startsWith('p-')){const x=D.plans.find(x=>`p-${x.id}`===h);html=x?planDetail(x):plans()}else if(h.startsWith('theory-')){const x=D.theories.find(x=>`theory-${x.id}`===h);html=x?theoryDetail(x):theories()}else if(h.startsWith('lesson-')){const x=(D.deepUnits||[]).find(x=>`lesson-${x.id}`===h);html=x?lessonDetail(x):lessons()}else html=home();app.innerHTML=html;app.focus({preventScroll:true});document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===navKey(h)));bind();if(h==='exam'&&state.exam&&!state.exam.finished)startExamTimer();}
  function startExamTimer(){examTimer=setInterval(()=>{const el=document.getElementById('exam-timer');if(!state.exam||state.exam.finished)return;const left=Math.max(0,state.exam.endsAt-Date.now());if(el){el.textContent=formatTime(left);el.classList.toggle('urgent',left<5*60*1000)}if(left===0){state.exam.finished=true;recordActivity('انتهت محاكاة الامتحان','تم التسليم تلقائيًا');render()}},1000)}
  function bind(){document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{state.qcmFilters[b.dataset.filter]=b.dataset.value;state.qcmIndex=0;render()}));document.getElementById('qcm-search')?.addEventListener('input',e=>{state.qcmFilters.query=e.target.value.trim();state.qcmIndex=0;save();rerenderSearch(e.target)});document.getElementById('scheme-search')?.addEventListener('input',e=>{state.qcmFilters.query=e.target.value.trim();rerenderSearch(e.target)});document.getElementById('term-search')?.addEventListener('input',e=>{state.qcmFilters.query=e.target.value.trim();rerenderSearch(e.target)});document.querySelectorAll('[data-qcm-option]').forEach(b=>b.addEventListener('click',()=>{const pool=qcmPool();const q=pool[state.qcmIndex];const selected=Number(b.dataset.qcmOption);const history=state.qcmHistory[q.id]||{attempts:0,correct:0,wrong:0,lastAt:0};history.attempts++;history.correct+=selected===q.answer?1:0;history.wrong+=selected===q.answer?0:1;history.lastAt=Date.now();state.qcmHistory[q.id]=history;state.qcmAnswers[q.id]=selected;recordActivity('أجبت عن سؤال',`${domainName(q.domain)} · ${selected===q.answer?'صحيح':'يحتاج مراجعة'}`);render()}));document.getElementById('next-qcm')?.addEventListener('click',()=>{const pool=qcmPool();state.qcmIndex=state.qcmIndex<pool.length-1?state.qcmIndex+1:0;render()});document.querySelectorAll('[data-qcm-jump]').forEach(b=>b.addEventListener('click',()=>{state.qcmIndex=Number(b.dataset.qcmJump);render()}));document.getElementById('start-focus')?.addEventListener('click',()=>{state.focus=true;document.body.classList.add('focus-mode');render()});document.getElementById('exit-focus')?.addEventListener('click',()=>{state.focus=false;document.body.classList.remove('focus-mode');render()});document.querySelectorAll('[data-sit-option]').forEach(b=>b.addEventListener('click',()=>{const s=D.situations[state.situationIndex];state.situationAnswers[s.id]=Number(b.dataset.sitOption);recordActivity('حللت وضعية مهنية',s.domain);render()}));document.getElementById('next-situation')?.addEventListener('click',()=>{state.situationIndex=(state.situationIndex+1)%D.situations.length;render()});document.querySelectorAll('[data-sit-jump]').forEach(b=>b.addEventListener('click',()=>{state.situationIndex=Number(b.dataset.sitJump);render()}));document.querySelector('[data-flip]')?.addEventListener('click',()=>{state.flashFlipped=!state.flashFlipped;render()});document.querySelectorAll('[data-rate]').forEach(b=>b.addEventListener('click',()=>{const deck=flashDeck();const card=deck[state.flashIndex%deck.length];const rating=b.dataset.rate;const prev=state.flashSchedule[card.id]||{repetitions:0,intervalDays:0,easeFactor:2.5};const interval=rating==='tomorrow'?1:rating==='today'?Math.max(1,Math.min(6,(prev.intervalDays||0)+1)):Math.max(7,Math.round((prev.intervalDays||1)*2.5));state.flashSchedule[card.id]={repetitions:rating==='tomorrow'?0:prev.repetitions+1,intervalDays:interval,easeFactor:Math.max(1.3,prev.easeFactor+(rating==='mastered'?.1:-.15)),nextReviewAt:Date.now()+interval*86400000};state.flashRatings[card.id]=rating==='mastered'?'mastered':'scheduled';recordActivity('راجعت بطاقة',`${card.front} · ${interval} يوم`);state.flashFlipped=false;state.flashIndex=0;save();render()}));document.getElementById('next-card')?.addEventListener('click',()=>{state.flashIndex=(state.flashIndex+1)%flashDeck().length;state.flashFlipped=false;render()});document.getElementById('prev-card')?.addEventListener('click',()=>{state.flashIndex=(state.flashIndex-1+flashDeck().length)%flashDeck().length;state.flashFlipped=false;render()});document.getElementById('start-exam')?.addEventListener('click',startExam);document.querySelectorAll('[data-exam-option]').forEach(b=>b.addEventListener('click',()=>{if(!state.exam||state.exam.finished)return;const q=D.qcm.find(x=>x.id===state.exam.questions[state.exam.current]);state.exam.answers[q.id]=Number(b.dataset.examOption);save();render()}));document.getElementById('next-exam')?.addEventListener('click',()=>{if(state.exam.current<state.exam.questions.length-1)state.exam.current++;else toast('راجع الشبكة ثم اضغط على تسليم الإجابات');save();render()});document.querySelectorAll('[data-exam-jump]').forEach(b=>b.addEventListener('click',()=>{state.exam.current=Number(b.dataset.examJump);save();render()}));document.getElementById('flag-exam')?.addEventListener('click',()=>{const id=state.exam.questions[state.exam.current];state.exam.flags=state.exam.flags.includes(id)?state.exam.flags.filter(x=>x!==id):[...state.exam.flags,id];save();render()});document.getElementById('submit-exam')?.addEventListener('click',()=>{state.exam.finished=true;recordActivity('سلّمت محاكاة الامتحان','راجع نقاط الضعف حسب المجال');render()});document.getElementById('restart-exam')?.addEventListener('click',()=>{state.exam=null;render()});document.querySelectorAll('[data-jury]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.jury);state.jury=state.jury.includes(i)?state.jury.filter(x=>x!==i):[...state.jury,i];save();render()}));document.getElementById('reset-progress')?.addEventListener('click',()=>{if(!window.confirm('سيتم حذف سجل المراجعة والنتائج المحفوظة على هذا الجهاز. هل تريد المتابعة؟'))return;state.qcmIndex=0;state.situationIndex=0;state.flashIndex=0;state.flashFlipped=false;state.inclusiveQuizIndex=0;state.inclusiveQuizScore=0;state.inclusiveQuizPicked=null;state.qcmAnswers={};state.qcmHistory={};state.situationAnswers={};state.flashRatings={};state.flashSchedule={};state.exam=null;state.readSchemes=[];state.readTerms=[];state.jury=[];state.activities=[];state.studyDays=[];state.readLessons=[];state.activeUnitId=null;state.activeUnitDate='';save();toast('تمت إعادة ضبط التقدم');render()});document.querySelectorAll('[data-inclusive-answer]').forEach(b=>b.addEventListener('click',()=>{const q=D.inclusive.quiz[state.inclusiveQuizIndex];state.inclusiveQuizPicked=Number(b.dataset.inclusiveAnswer);if(state.inclusiveQuizPicked===q.answer)state.inclusiveQuizScore++;render()}));document.getElementById('next-inclusive-quiz')?.addEventListener('click',()=>{state.inclusiveQuizIndex++;state.inclusiveQuizPicked=null;render()});document.querySelectorAll('[data-pillar]').forEach(b=>b.addEventListener('click',()=>{state.inclusivePillar=Number(b.dataset.pillar);save();render()}));document.getElementById('next-pillar')?.addEventListener('click',()=>{state.inclusivePillar=(state.inclusivePillar+1)%D.inclusive.pillars.length;save();render()});document.getElementById('restart-inclusive-quiz')?.addEventListener('click',()=>{state.inclusiveQuizIndex=0;state.inclusiveQuizScore=0;state.inclusiveQuizPicked=null;render()});document.getElementById('resource-search')?.addEventListener('input',e=>{state.resourceSearch=e.target.value.trim();save();rerenderSearch(e.target)});document.querySelectorAll('[data-resource-filter]').forEach(b=>b.addEventListener('click',()=>{state.resourceFilter=b.dataset.resourceFilter;save();render()}));document.querySelectorAll('[data-path-action]').forEach(button=>button.addEventListener('click',()=>{const unit=D.deepUnits.find(item=>item.id===button.dataset.unit);if(!unit)return;const action=button.dataset.pathAction;let target='#qcm';if(action==='quiz'){state.qcmFilters={...state.qcmFilters,domain:unit.id,difficulty:'all',status:'all',query:''};state.qcmIndex=0;target='#qcm'}else if(action==='situation'){const index=D.situations.findIndex(item=>(unit.situationIds||[]).includes(item.id));if(index>=0)state.situationIndex=index;target='#situations'}else if(action==='flashcards'){const deck=flashDeck();const index=deck.findIndex(card=>(unit.cardIds||[]).includes(card.id));state.flashIndex=Math.max(0,index);target='#flashcards'}save();if(location.hash===target)render();else location.hash=target}));document.querySelectorAll('[data-term-category]').forEach(b=>b.addEventListener('click',()=>{state.termCategory=b.dataset.termCategory;save();render()}));}
  document.getElementById('theme-toggle')?.addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=state.theme;writeStorage('morchid-theme',state.theme);syncGlobalControls()});
  document.getElementById('focus-toggle')?.addEventListener('click',()=>{state.focus=!state.focus;document.body.classList.toggle('focus-mode',state.focus);syncGlobalControls();toast(state.focus?'تم تفعيل وضع التركيز':'تم إيقاف وضع التركيز')});
  document.addEventListener('click',event=>{const button=event.target.closest?.('[data-term-category]');if(!button)return;state.termCategory=button.dataset.termCategory;save();render()});
  document.documentElement.dataset.theme=state.theme;document.body.classList.toggle('focus-mode',state.focus);syncGlobalControls();addEventListener('hashchange',()=>{state.qcmFilters.query='';render()});render();if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
})();
